cd /home/user/openai-nlogn-wiki/runs/P1/exegenius/tasks; cat > 0002-background.answer.json <<'EOF'
{
  "summary": "The reader has an undergraduate computer science education: discrete mathematics (sets, functions, induction, summations, recurrences, basic number theory and elementary group/ring/field vocabulary), an algorithms course (recursion, divide and conquer, schoolbook and Karatsuba multiplication, the FFT at the level of the divide-and-conquer recursion, solving recurrences), single-variable calculus (limits, exponentials, logarithms) and one course in linear algebra and complex numbers. They know Turing machines and big-O at an introductory level, but have not studied fast integer multiplication beyond Karatsuba, Schönhage-Strassen or Harvey-van der Hoeven, numerical error analysis, bilinear forms over finite fields, matrix factorizations such as Bruhat decompositions, or tape-level algorithm engineering.",
  "known": [
    {
      "name": "Binary representation and schoolbook arithmetic",
      "aliases": ["binary numerals", "bits", "radix representation", "base-b digits", "carry propagation", "schoolbook addition", "schoolbook multiplication", "most significant bit", "leading zeroes"],
      "gloss": "A nonnegative integer is written as a string of bits (or digits in base b) with the leftmost digit most significant, and addition and multiplication by hand take time quadratic in the length using carries."
    },
    {
      "name": "Floor, ceiling and logarithms",
      "aliases": ["floor function", "ceiling function", "lg", "log base 2", "binary logarithm", "iterated logarithm", "log*", "rounding to nearest integer"],
      "gloss": "The notations floor(x), ceiling(x), lg x = log_2 x and the iterated logarithm, together with the rule that an integer v needs floor(log_2 v)+1 bits."
    },
    {
      "name": "Exponentials and elementary inequalities",
      "aliases": ["exp", "e^x", "1+x <= e^x", "limits", "powers of two", "real exponents", "fractional powers"],
      "gloss": "Calculus-level facts on exponentials and powers with real exponents, limits, and simple inequalities such as 1+x <= e^x used to compare growth rates."
    },
    {
      "name": "Summation, telescoping sums and geometric series",
      "aliases": ["sigma notation", "telescoping", "geometric sum", "partial sums"],
      "gloss": "Finite sums written with Σ, sums in which consecutive terms cancel, and the closed form of geometric series."
    },
    {
      "name": "Recurrences and the recursion tree",
      "aliases": ["recurrence relation", "solving recurrences", "master theorem", "divide and conquer", "recursive cost", "unrolling a recurrence"],
      "gloss": "A cost T(n) defined in terms of smaller instances, solved by unrolling or a recursion tree to obtain a closed-form bound."
    },
    {
      "name": "Karatsuba and classical multiplication algorithms",
      "aliases": ["Karatsuba multiplication", "Toom-Cook", "Schönhage-Strassen", "O(n^2) multiplication", "O(n^{log_2 3})"],
      "gloss": "The schoolbook O(n^2) multiplication and Karatsuba's divide-and-conquer O(n^{log_2 3}) multiplication, as taught in algorithms courses, as the baseline against which faster methods are compared."
    },
    {
      "name": "Recursion, call stack and subroutines",
      "aliases": ["recursive call", "call stack", "stack data structure", "program counter", "subroutine", "black-box call"],
      "gloss": "A procedure calling smaller instances of itself, with a stack of suspended calls, and the idea of using a procedure as a black box with a stated cost."
    },
    {
      "name": "Sets, functions, bijections and permutations",
      "aliases": ["[n]", "index set", "Cartesian product", "bijection", "permutation", "inverse function", "composition of functions", "injective", "surjective", "partial permutation"],
      "gloss": "Index sets such as [n]={0,...,n-1}, product sets, functions and their composition, and permutations as bijections of a finite set."
    },
    {
      "name": "Mathematical induction and proof techniques",
      "aliases": ["proof by induction", "induction on the number of steps", "proof by contradiction", "invariant", "loop invariant", "contrapositive"],
      "gloss": "Standard proof methods for correctness and cost claims: induction, contradiction, and invariants maintained across steps."
    },
    {
      "name": "Prime numbers and trial division",
      "aliases": ["primes", "prime", "odd prime", "trial division", "primality testing by division", "coprime integers", "relatively prime", "prime factorization"],
      "gloss": "A prime has no divisors besides 1 and itself; integers are uniquely products of primes; primality of small numbers can be found by dividing by all smaller candidates."
    },
    {
      "name": "Groups, rings and fields",
      "aliases": ["algebraic structure", "ring", "field", "group", "finite field", "F_2", "GF(2)", "ring of residues Z/qZ", "units of a ring", "quotient ring", "cyclic group"],
      "gloss": "Basic abstract-algebra vocabulary: sets with addition and multiplication satisfying axioms, with fields (such as the rationals, the complex numbers and the two-element field F_2) allowing division, and cyclic groups Z/qZ."
    },
    {
      "name": "XOR and arithmetic over F_2",
      "aliases": ["exclusive or", "bitwise XOR", "addition mod 2", "parity", "bit flip", "bitwise operations", "bit shift"],
      "gloss": "The exclusive-or of two bits is their sum modulo 2, applied coordinatewise to bit strings, and is its own inverse."
    },
    {
      "name": "Special matrices and matrix algebra",
      "aliases": ["identity matrix", "diagonal matrix", "permutation matrix", "invertible matrix", "matrix inverse", "transpose", "matrix product", "standard basis vector", "lower triangular matrix", "block matrix", "matrix-vector product"],
      "gloss": "Matrix multiplication, inverses and transposes, and the identity, diagonal, permutation and triangular matrices, together with standard basis vectors e_j."
    },
    {
      "name": "Triangle inequality and norm bounds",
      "aliases": ["triangle inequality", "modulus of a sum", "|z+w| <= |z|+|w|", "maximum norm", "sup norm", "absolute error", "error bound"],
      "gloss": "The modulus of a sum is at most the sum of moduli, used to bound approximation errors that add."
    },
    {
      "name": "Rational numbers and dyadic fractions",
      "aliases": ["rational numbers", "fractions", "dyadic rational", "denominator a power of 2", "numerator and denominator", "lowest terms"],
      "gloss": "Quotients of integers, and in particular numbers whose denominator is a power of two, which have finite binary expansions."
    },
    {
      "name": "Deterministic algorithms and worst-case time",
      "aliases": ["deterministic machine", "worst-case running time", "time complexity", "fixed finite alphabet", "linear time scan"],
      "gloss": "An algorithm with no randomness whose cost is the maximum number of steps over all inputs of a given length, with a single pass over input called linear time."
    },
    {
      "name": "Entrywise operations on arrays and vectors",
      "aliases": ["pointwise product", "componentwise product", "Hadamard product", "vector of coefficients", "coefficient list", "array indexing", "multi-index"],
      "gloss": "Operations applied independently to each coordinate of a list or multi-indexed array, and the identification of polynomials, vectors and arrays with coefficient lists."
    }
  ]
}
EOF
cd /home/user/openai-nlogn-wiki/runs/P1 && exegenius submit 0002-background

